#include <stdio.h>
#include <stdbool.h>

static int nextNumber(int n) {
    int total = 0;
    while (n > 0) {
        int digit = n % 10;
        total += digit * digit;
        n /= 10;
    }
    return total;
}

static bool isSeen(const int seen[], int count, int value) {
    for (int i = 0; i < count; i++) {
        if (seen[i] == value) return true;
    }
    return false;
}

bool isHappy(int n) {
    int seen[100];
    int count = 0;
    while (n != 1 && !isSeen(seen, count, n)) {
        seen[count++] = n;
        n = nextNumber(n);
    }
    return n == 1;
}

